package docgen

import (
	"archive/zip"
	"bytes"
	"io"
	"strings"
	"testing"

	docx "github.com/mmonterroca/docxgo/v2"
	"github.com/mmonterroca/docxgo/v2/domain"
	"github.com/stretchr/testify/require"
)

// The DOCX engine tests (add-document-editing task 4.2/4.5): the skeleton
// fixtures are authored by docxgo itself — no binary fixtures, no network —
// and the generated bytes are re-read through docxgo (paragraphs, styles)
// and, where the library surface has no getter, through the part's XML.

// sampleMarkdown is the content every engine maps: the minimal markdown
// vocabulary (h1–h3, paragraphs, bullet and numbered lists).
const sampleMarkdown = "# Q3 Report\n\nOpening paragraph.\n" +
	"## Results\n\nSecond paragraph.\n### Detail\n" +
	"- first bullet\n- second bullet\n" +
	"  - nested bullet\n" +
	"1. first step\n2. second step\n"

// docxPart extracts one XML part from generated DOCX bytes for the
// assertions docxgo's read surface cannot express (the paragraph style
// references). It fails the test when the part is missing.
func docxPart(t *testing.T, data []byte, name string) string {
	t.Helper()
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	require.NoError(t, err)
	for _, f := range zr.File {
		if f.Name != name {
			continue
		}
		rc, err := f.Open()
		require.NoError(t, err)
		defer rc.Close()
		raw, err := io.ReadAll(rc)
		require.NoError(t, err)
		return string(raw)
	}
	t.Fatalf("part %s not found", name)
	return ""
}

// docxParagraphs re-reads the generated bytes and returns the body
// paragraphs' texts, in document order.
func docxParagraphs(t *testing.T, data []byte) []string {
	t.Helper()
	doc, err := docx.OpenDocumentFromBytes(data)
	require.NoError(t, err)
	var texts []string
	for _, p := range doc.Paragraphs() {
		texts = append(texts, p.Text())
	}
	return texts
}

// TestRenderDOCX_ConfigFlavorDefaults covers the nil-preset config flavor:
// the built-in default template renders the whole minimal markdown
// vocabulary, headings styled with the built-in Heading styles.
func TestRenderDOCX_ConfigFlavorDefaults(t *testing.T) {
	data, err := renderDOCX(nil, nil, sampleMarkdown)
	require.NoError(t, err)

	// Every block landed, in document order (consecutive plain lines join
	// into one paragraph).
	texts := docxParagraphs(t, data)
	require.Equal(t, []string{
		"Q3 Report",
		"Opening paragraph.",
		"Results",
		"Second paragraph.",
		"Detail",
		"• first bullet",
		"• second bullet",
		"• nested bullet",
		"1. first step",
		"2. second step",
	}, texts)

	// The heading style references are in the body XML.
	body := docxPart(t, data, "word/document.xml")
	require.Contains(t, body, `<w:pStyle w:val="Heading1"></w:pStyle>`)
	require.Contains(t, body, `<w:pStyle w:val="Heading2"></w:pStyle>`)
	require.Contains(t, body, `<w:pStyle w:val="Heading3"></w:pStyle>`)
	require.Contains(t, body, `<w:pStyle w:val="ListParagraph"></w:pStyle>`)
	require.NotContains(t, body, "w:numPr", "lists are marked text, not numbering references")
}

// TestRenderDOCX_ConfigPresetOverrides covers the spec's config-preset
// scenario: the preset's font, heading, page, and footer parameters
// override the built-in default template's styles.
func TestRenderDOCX_ConfigPresetOverrides(t *testing.T) {
	regular := false
	preset := &DOCXPreset{
		Flavor: PresetFlavorConfig,
		Fonts: &DOCXFonts{
			BodyFamily:    "Courier New",
			BodySize:      14,
			HeadingFamily: "Georgia",
			HeadingSize:   20,
		},
		Heading: &DOCXHeadingStyle{Color: "#AA11BB", Bold: &regular},
		Page:    &DOCXPageSetup{Size: "letter", Orientation: "landscape", MarginInches: 2},
		Footer:  &DOCXFooterStyle{Text: "ACME Confidential", ShowPageNumber: true},
	}
	data, err := renderDOCX(preset, nil, "# Heading Text\n\nBody text.")
	require.NoError(t, err)

	// The style overrides live in styles.xml — the artifact Word renders.
	// (The library's read-back of style run properties is lossy, so the
	// assertions read the part the preset actually controls.)
	styles := docxPart(t, data, "word/styles.xml")
	require.Contains(t, styles, `<w:rFonts w:ascii="Courier New" w:hAnsi="Courier New"></w:rFonts>`)
	require.Contains(t, styles, `<w:sz w:val="28"></w:sz>`, "the body size: 14pt = 28 half-points")
	require.Contains(t, styles, `<w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"></w:rFonts>`)
	require.Contains(t, styles, `<w:sz w:val="40"></w:sz>`, "the Heading 1 size: 20pt = 40 half-points")
	require.Contains(t, styles, `<w:color w:val="AA11BB"></w:color>`)

	// Landscape swapped the letter page's dimensions (width > height) and
	// the margins are two inches on every side.
	doc, err := docx.OpenDocumentFromBytes(data)
	require.NoError(t, err)
	sec, err := doc.DefaultSection()
	require.NoError(t, err)
	size := sec.PageSize()
	require.Greater(t, size.Width, size.Height, "landscape letter")
	require.Equal(t, domain.PageSize{Width: domain.PageSizeLetter.Height, Height: domain.PageSizeLetter.Width}, size)
	margins := sec.Margins()
	require.Equal(t, 2880, margins.Top)
	require.Equal(t, 2880, margins.Left)

	// The footer carries the literal text and the page-number field (the
	// trailing 1 is the field's cached page result). The field code itself
	// lives in the footer part — the library's read-back of run fields on
	// a preserved footer is lossy.
	footer, err := sec.Footer(domain.FooterDefault)
	require.NoError(t, err)
	paras := footer.Paragraphs()
	require.Len(t, paras, 1)
	require.True(t, strings.HasPrefix(paras[0].Text(), "ACME Confidential"))
	require.Contains(t, docxPart(t, data, "word/footer1.xml"), "PAGE")
}

// TestRenderDOCX_TemplateFlavor covers the template-document flavor: the
// skeleton's content and styles are preserved, its {{title}} placeholder
// is filled from the markdown's first heading, and the content is appended
// into the styled body region (spec document-generation "Preset
// round-trips" rides the service; this is the engine half).
func TestRenderDOCX_TemplateFlavor(t *testing.T) {
	// The skeleton, authored by docxgo: a static opening line and a cover
	// paragraph whose {{title}} is split across two runs, the way Word
	// itself splits tokens.
	skeletonDoc := docx.NewDocument()
	addPara := func(runs ...string) {
		t.Helper()
		para, err := skeletonDoc.AddParagraph()
		require.NoError(t, err)
		for _, r := range runs {
			run, err := para.AddRun()
			require.NoError(t, err)
			require.NoError(t, run.SetText(r))
		}
	}
	addPara("Static introduction.")
	addPara("{{", "title}} — Weekly Review")
	var skeletonBytes bytes.Buffer
	_, err := skeletonDoc.WriteTo(&skeletonBytes)
	require.NoError(t, err)

	data, err := renderDOCX(nil, skeletonBytes.Bytes(), "# Q3 Report\n\nGenerated body.")
	require.NoError(t, err)

	texts := docxParagraphs(t, data)
	require.Equal(t, []string{
		"Static introduction.",
		"Q3 Report — Weekly Review", // the run-split token filled
		"Q3 Report",                 // the content's heading, after the skeleton's body
		"Generated body.",
	}, texts)
}

// TestRenderDOCX_TemplateFlavorWithoutHeading covers the degraded title:
// content with no heading fills {{title}} with the empty string — a
// generated document never leaks the template's tokens.
func TestRenderDOCX_TemplateFlavorWithoutHeading(t *testing.T) {
	skeletonDoc := docx.NewDocument()
	para, err := skeletonDoc.AddParagraph()
	require.NoError(t, err)
	run, err := para.AddRun()
	require.NoError(t, err)
	require.NoError(t, run.SetText("Cover: {{title}}"))
	var skeleton bytes.Buffer
	_, err = skeletonDoc.WriteTo(&skeleton)
	require.NoError(t, err)

	data, err := renderDOCX(nil, skeleton.Bytes(), "Just a paragraph.")
	require.NoError(t, err)
	texts := docxParagraphs(t, data)
	require.Equal(t, []string{"Cover: ", "Just a paragraph."}, texts)
}

// TestRenderDOCX_RejectsHostileSkeleton pins the D9 boundary: a payload
// that is not a DOCX renders as a readable error, never a panic.
func TestRenderDOCX_RejectsHostileSkeleton(t *testing.T) {
	_, err := renderDOCX(nil, []byte("this is not a zip"), "# Broken")
	require.Error(t, err)
	require.Contains(t, err.Error(), "open DOCX template")
}

// TestParseBlocks pins the minimal markdown mapping both engines share:
// headings, joined paragraphs, and the two list kinds with nesting.
func TestParseBlocks(t *testing.T) {
	blocks := parseBlocks(sampleMarkdown)
	require.Equal(t, []block{
		{Kind: blockHeading1, Text: "Q3 Report"},
		{Kind: blockParagraph, Text: "Opening paragraph."},
		{Kind: blockHeading2, Text: "Results"},
		{Kind: blockParagraph, Text: "Second paragraph."},
		{Kind: blockHeading3, Text: "Detail"},
		{Kind: blockBullet, Text: "first bullet"},
		{Kind: blockBullet, Text: "second bullet"},
		{Kind: blockBullet, Level: 1, Text: "nested bullet"},
		{Kind: blockNumbered, Text: "first step"},
		{Kind: blockNumbered, Text: "second step"},
	}, blocks)
}

// TestParseBlocks_DegradedConstructs covers the mapping's edges: deeper
// headings degrade to h3, other markers ride as paragraph text, and a
// sentence's first period is not a numbered list.
func TestParseBlocks_DegradedConstructs(t *testing.T) {
	blocks := parseBlocks("#### Deep\n> Quote-ish\n3.14 is not a list\n+ plus bullet\n2) paren list")
	require.Equal(t, []block{
		{Kind: blockHeading3, Text: "Deep"},
		{Kind: blockParagraph, Text: "> Quote-ish 3.14 is not a list"},
		{Kind: blockBullet, Text: "plus bullet"},
		{Kind: blockNumbered, Text: "paren list"},
	}, blocks)
	require.True(t, blocks[len(blocks)-1].isNumbered())
	require.False(t, blocks[1].isList())
}
